cd /workspace
duckdb work.duckdb -c "
LOAD spatial;
-- q09
SELECT 'q09' q, count(*) FILTER (WHERE by_primary OR by_aggregate) v FROM matched;
-- q10
SELECT 'q10' q, count(*) FILTER (WHERE by_primary) single_rule,
       count(*) FILTER (WHERE (by_primary OR by_aggregate) AND NOT by_primary) agg_only FROM matched;
-- q11
SELECT 'q11' q, min(max_single_frac) mn, avg(max_single_frac) avg_s, avg(union_frac) avg_u
FROM matched WHERE by_primary OR by_aggregate;
-- q12
SELECT 'q12' q, count(*) FILTER (WHERE NOT by_primary AND NOT by_aggregate) n_excluded FROM matched;
" 2>&1 | tail -30

cd /workspace
duckdb work.duckdb -c "
LOAD spatial;
SET geometry_always_xy = true;
SELECT sum(ST_Area_Spheroid(f.geometry))/10000.0 AS ha_xy
FROM matched m JOIN fields_env f ON f.Id=m.Id WHERE by_primary OR by_aggregate;
" 2>&1 | tail -6
duckdb work.duckdb -c "
LOAD spatial;
SET geometry_always_xy = false;
SELECT sum(ST_Area_Spheroid(f.geometry))/10000.0 AS ha_latlon
FROM matched m JOIN fields_env f ON f.Id=m.Id WHERE by_primary OR by_aggregate;
" 2>&1 | tail -6

cd /workspace
duckdb work.duckdb -c "
LOAD spatial;
-- reproject to EPSG:5880 (Brazil Polyconic, metres) for a check; assign source 4326
SELECT sum(ST_Area(ST_Transform(ST_FlipCoordinates(ST_GeomFromText(ST_AsText(f.geometry))), 'EPSG:4326','EPSG:5880')))/10000.0 AS ha_5880_flip
FROM matched m JOIN fields_env f ON f.Id=m.Id WHERE by_primary OR by_aggregate;
" 2>&1 | tail -8
echo "=== try transform assuming xy (no flip) ==="
duckdb work.duckdb -c "
LOAD spatial;
SET geometry_always_xy=true;
SELECT sum(ST_Area(ST_Transform(f.geometry,'EPSG:4326','EPSG:5880')))/10000.0 AS ha_5880
FROM matched m JOIN fields_env f ON f.Id=m.Id WHERE by_primary OR by_aggregate;
" 2>&1 | tail -8

cd /workspace
duckdb work.duckdb <<'EOF' 2>&1 | tail -40
LOAD spatial;
SET geometry_always_xy=true;
-- flagged cadasters: have >=1 in-scope field with post-2020 loss
CREATE OR REPLACE TABLE flagged AS
SELECT cod_imovel, sum(d2124) AS post2020_loss_ha
FROM mfx WHERE in_scope AND d2124>0
GROUP BY cod_imovel;

-- dominant class per cadaster over ALL matched fields (area-weighted, tie->lower mb)
CREATE OR REPLACE TABLE dom AS
SELECT cod_imovel, mb AS dominant_mb FROM (
  SELECT cod_imovel, mb, sum(field_ha) ha,
         row_number() OVER (PARTITION BY cod_imovel ORDER BY sum(field_ha) DESC, mb ASC) rn
  FROM mfx GROUP BY cod_imovel, mb
) WHERE rn=1;

SELECT count(*) n_flagged FROM flagged;
SELECT d.dominant_mb, count(*) n FROM flagged f JOIN dom d USING(cod_imovel) GROUP BY 1 ORDER BY 1;

-- cadaster centroids (from CAR polygon) and muni code
CREATE OR REPLACE TABLE cad_geo AS
SELECT c.cod_imovel, c.municipio,
       split_part(c.cod_imovel,'-',2) AS cod_ibge,
       ST_Centroid(c.geometry) AS cen
FROM car_parcels c;
SELECT DISTINCT cod_ibge, municipio FROM cad_geo ORDER BY cod_ibge;
EOF

