FROM read_parquet('$FAC')
WHERE tier IN ('intake_point','slaughter_point','mill_point','gravity_catchment')
  AND ST_Intersects(geometry, ST_MakeEnvelope(-55.0,-19.0,-47.5,-12.0));
SELECT tier, count(*) n, count(*) FILTER (WHERE weight>=1000) ge1000 FROM fac GROUP BY tier ORDER BY tier;
CREATE OR REPLACE TABLE membership AS
SELECT entity_id, entity_kind, tier, weight, basis, geom_method, geometry
FROM read_parquet('$FAC')
WHERE tier='membership_muni' AND entity_id IN ('5207600','5212204','5219258');
SELECT count(*) memb FROM membership;
EOF

