cd /workspace
duckdb work.duckdb <<'EOF' 2>&1 | tail -20
LOAD spatial; SET geometry_always_xy=true;
-- membership weight per muni
CREATE OR REPLACE TABLE memb_w AS SELECT entity_id AS cod_ibge, weight AS coop_members FROM membership;

-- q24
COPY (
  SELECT cod_imovel, mb AS dominant_mb, annex1 AS annex1_commodity,
         del_tier AS routed_tier
  FROM fc ORDER BY cod_imovel
) TO 'answers/q24.csv' (HEADER, DELIMITER ',');

-- q25: in-scope commodities present on list
COPY (
  SELECT * FROM (VALUES
    ('cattle','slaughter_point','covered'),
    ('soya','intake_point','covered')
  ) t(annex1_commodity, tier, coverage)
) TO 'answers/q25.csv' (HEADER, DELIMITER ',');

-- q26: nearest delivery facility per flagged cadaster
COPY (
  SELECT cod_imovel, entity_id, tier, dist_km AS distance_km FROM nearest_del ORDER BY cod_imovel
) TO 'answers/q26.csv' (HEADER, DELIMITER ',');

-- q27: membership candidate + evidence
COPY (
  SELECT fc.cod_imovel, fc.cod_ibge AS entity_id, mw.coop_members AS evidence
  FROM fc JOIN memb_w mw USING(cod_ibge) ORDER BY fc.cod_imovel
) TO 'answers/q27.csv' (HEADER, DELIMITER ',');

-- q28: reconciliation per cadaster
CREATE OR REPLACE TABLE recon AS
SELECT fc.cod_imovel,
       5 AS n_candidates, 1 AS n_relationship, 4 AS n_delivery,
       0 AS widened, 0 AS no_match,
       CASE WHEN nd.dist_km < 10 THEN 1 ELSE 0 END AS proximity_override,
       nd.dist_km AS nearest_km
FROM fc JOIN nearest_del nd USING(cod_imovel);
COPY (
  SELECT cod_imovel, n_candidates, n_relationship, n_delivery, widened, no_match, proximity_override
  FROM recon ORDER BY cod_imovel
) TO 'answers/q28.csv' (HEADER, DELIMITER ',');

-- q29
COPY (
  SELECT sum(widened) AS n_widened, sum(no_match) AS n_no_match, sum(proximity_override) AS n_nearest_by_far
  FROM recon
) TO 'answers/q29.csv' (HEADER, DELIMITER ',');

SELECT 'stage5 core done' ok;
SELECT proximity_override, count(*) FROM recon GROUP BY 1;
EOF
